46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioOutput {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	};
63	
64	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
65	
66	const quote = (step: QuoteStep): QuoteResult => {
67	  const policyBase = step.items.reduce((sum, item) => sum + basePremiumOf(item), 0);
68	  const premiumBeforeRounding =
69	    policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
70	  return { premium: Math.ceil(premiumBeforeRounding) };
71	};
72	
73	export const runScenario = (scenario: Scenario): ScenarioOutput => {
74	  return { results: scenario.steps.map((step) => quote(step as QuoteStep)) };
75	};
